import com.wolinski.shop.platform.ShopProblem;
import java.util.regex.Pattern;

/** Rates as whole basis points in a long: 12.5% is 1250. See ADR 8. */
final class BasisPoints {

    private static final long WHOLE = 10_000;
    private static final Pattern PERCENT_TEXT = Pattern.compile("\\d{1,3}(\\.\\d{1,2})?");

    private BasisPoints() {
    }

    /** Parses text such as "12.5" into basis points. Accepts (0, 100] with at most two decimals. */
    static long ofPercent(String text) {
        if (null == text || false == PERCENT_TEXT.matcher(text.trim()).matches()) {
            throw invalid(text);
        }
        String[] parts = text.trim().split("\\.", 2);
        long whole = Long.parseLong(parts[0]);
        long hundredths = parts.length == 2 ? Long.parseLong((parts[1] + "0").substring(0, 2)) : 0;
        long basisPoints = whole * 100 + hundredths;
        if (basisPoints <= 0 || basisPoints > WHOLE) {
            throw invalid(text);
        }
        return basisPoints;
    }

    /** The part of amount that rate covers, rounded half up to a whole minor unit. */
    static long of(long amount, long basisPoints) {
        return (amount * basisPoints + WHOLE / 2) / WHOLE;
    }

    private static ShopProblem invalid(String text) {
        return new ShopProblem("invalid-percent", "Not a percentage between 0 and 100: " + text);
    }
}
}

