{path=src/test/java/com/wolinski/shop/orders/internal/BasisPointsTest.java, content=package com.wolinski.shop.orders.internal;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.platform.ShopProblem;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class BasisPointsTest {

    @Test
    void parsesPercentTextIntoBasisPoints() {
        assertEquals(1250, BasisPoints.ofPercent("12.5"));
        assertEquals(1250, BasisPoints.ofPercent("12.50"));
        assertEquals(1205, BasisPoints.ofPercent("12.05"));
        assertEquals(1200, BasisPoints.ofPercent("12"));
        assertEquals(50, BasisPoints.ofPercent(" 0.5 "));
        assertEquals(10000, BasisPoints.ofPercent("100"));
    }

    @ParameterizedTest
    @ValueSource(strings = {"", "abc", "12,5", "-1", "+1", "1e2", "12.555", "12.", ".5", "101", "100.01", "0", "0.00", "1000"})
    void rejectsBadPercentText(String text) {
        ShopProblem problem = assertThrows(ShopProblem.class, () -> BasisPoints.ofPercent(text));
        assertEquals("invalid-percent", problem.code());
    }

    @Test
    void rejectsNull() {
        assertThrows(ShopProblem.class, () -> BasisPoints.ofPercent(null));
    }

    @Test
    void roundsHalfUpToWholeMinorUnits() {
        assertEquals(1, BasisPoints.of(100, 50));      // 0.5% of 1.00 PLN -> 0.01 PLN
        assertEquals(0, BasisPoints.of(99, 50));       // 0.495 -> 0
        assertEquals(12, BasisPoints.of(100, 1250));   // 12.5% of 100 = 12.5 -> 13
        assertEquals(13, BasisPoints.of(100, 1250));
        assertEquals(100, BasisPoints.of(100, 10000)); // 100% covers everything
    }
}
}

